(6159386, 908226, 23484, '<td valign="top">This is neat. Excellent capture.</td>', 'This is neat. Excellent capture.', '2010-09-11 21:18:27.000000', NULL, 1),
(6159394, 907377, 61788, '<td valign="top">I consider this one of the most successful in the challenge - nicey done. I see few triangles including one that is brightest part of the sky framed by the mountains below and darker sky above. However, have suggestions. Stick on right end of the boat distracts. I tried cropping and feel this image will rather gain if cropped from right about 30 pixels. It will cut boat, but looks fine to me. Then cropping half of the sky. This will concentrate attention to your main point of interest - sail and boat, but also will create diagonal with the sky triangle I mentioned. For the future - if at all possible to position camera higher, it would make water as a background for these poles with fishing net - right now they "contact" the other side of the bay with similar color. But, ... consider all above just compliments to very good work :) Hope to see this very high in results.</td>', 'I consider this one of the most successful in the challenge - nicey done. I see few triangles including one that is brightest part of the sky framed by the mountains below and darker sky above. However, have suggestions. Stick on right end of the boat distracts. I tried cropping and feel this image will rather gain if cropped from right about 30 pixels. It will cut boat, but looks fine to me. Then cropping half of the sky. This will concentrate attention to your main point of interest - sail and boat, but also will create diagonal with the sky triangle I mentioned. For the future - if at all possible to position camera higher, it would make water as a background for these poles with fishing net - right now they "contact" the other side of the bay with similar color. But, ... consider all above just compliments to very good work :) Hope to see this very high in results.', '2010-09-11 21:30:02.000000', NULL, 1),
(6159406, 908009, 61788, '<td valign="top">Nicely seen - good work. I think basic editing allows to use curves adjustment layer and probably it is possible to make different triangles more prominent here. Monochrome seems like right choice for the subject, but bluish color I feel is not the best choice. Hard to say though :)</td>', 'Nicely seen - good work. I think basic editing allows to use curves adjustment layer and probably it is possible to make different triangles more prominent here. Monochrome seems like right choice for the subject, but bluish color I feel is not the best choice. Hard to say though :)', '2010-09-11 21:51:18.000000', NULL, 1),
