(6161654, 908031, 105457, '<td valign="top">This photo has a bit of feeling of a snapshot, it looks like it has not been planned and is a bit out of focus.</td>', 'This photo has a bit of feeling of a snapshot, it looks like it has not been planned and is a bit out of focus.', '2010-09-14 12:48:23.000000', NULL, 1),
(6161655, 908298, 105457, '<td valign="top">This is a good abstract picture, but I think the voters will be a bit confused about the triangle part, it''s a bit hidden. I would increase the contrast and brightness to improve this photo.</td>', 'This is a good abstract picture, but I think the voters will be a bit confused about the triangle part, it''s a bit hidden. I would increase the contrast and brightness to improve this photo.', '2010-09-14 12:49:37.000000', NULL, 1),
