(6162300, 907377, 114285, '<td valign="top">Wow, this ones brilliant, I did''nt see it during the challenge but would''ve given it a 10, should''ve placed higher. Can''t believe you got 5 - 3''s, honestly sometimes I wonder about the people voting on these challenges.</td>', 'Wow, this ones brilliant, I did''nt see it during the challenge but would''ve given it a 10, should''ve placed higher. Can''t believe you got 5 - 3''s, honestly sometimes I wonder about the people voting on these challenges.', '2010-09-15 01:10:07.000000', NULL, 0),
(6162310, 908226, 100831, '<td valign="top">A+ for the most interesting image in the challenge. Made me think.</td>', 'A+ for the most interesting image in the challenge. Made me think.', '2010-09-15 01:19:49.000000', NULL, 0),
(6162315, 907447, 104809, '<td valign="top">The name with the image did it for me on this one.  It was the one I rated highest.  I gave it a 9 and marked it a favorite.</td>', 'The name with the image did it for me on this one.  It was the one I rated highest.  I gave it a 9 and marked it a favorite.', '2010-09-15 01:25:40.000000', NULL, 0),
